+async function md5sum( files, folder ) {
+	if ( os.platform() === "win32" ) {
+		const rmd5 = /[a-f0-9]{32}/;
+		const sum = [];
+
+		for ( let i = 0; i < files.length; i++ ) {
+			const { stdout } = await exec( "certutil -hashfile " + files[ i ] + " MD5", {
+				cwd: folder
+			} );
+			sum.push( rmd5.exec( stdout )[ 0 ] + " " + files[ i ] );
+		}
+
+		return sum.join( "\n" );
