+
+				// console.log( refType );
+				refType = refType.replace( rendsWithHash, "" );
+				ticket.url = `https://github.com/${ refType }/issues/${ ticketId }`;
+				ticket.label = refType + ticket.label;
+			}
+
+			tickets.push( ticket );
+		}
+	);
+
+	return tickets;
+}
